-- إصلاحُ الملخَّصات المبتورة.
-- وُلِّد آليًّا بـ scripts/repair-truncated-summaries.py: كلُّ حرفٍ مُضافٍ
-- منقولٌ بحرفه من حقل body الخاصِّ بالصفِّ نفسِه، لا من خارجه.
BEGIN;
UPDATE sharia_rulings SET summary = 'قال النبي ﷺ: «إذا مات الإنسان انقطع عمله إلا من ثلاث: صدقة جارية، أو علم يُنتفع به، أو ولد صالح يدعو له» — رواه مسلم. وتشمل الصدقة الجارية: الوقف، والمسجد، وحفر البئر.'
  WHERE id = '028796d5-a783-416b-83b2-a96493fd59fc';
UPDATE sharia_rulings SET summary = 'أسباب الضعف تنقسم لقسمين: (1) ضعف في السند: كانقطاع السند (إرسال، إعضال، انقطاع)، وضعف الراوي (كذب، تدليس، سوء حفظ، جهالة). (2) ضعف في المتن: كالشذوذ (مخالفة الثقات)، والعلة القادحة الخفية…'
  WHERE id = '02c3292b-bc53-4430-981d-dfe3b64ec117';
UPDATE sharia_rulings SET summary = 'الأسهم المباحة تجب فيها الزكاة. وللعلماء طريقتان: (1) اعتبار الأسهم بضاعة تجارية: يُزكّى ما يخصك من قيمة الأصول الزكوية في الشركة (النقد والديون والمخزون). (2) إخراج 2.5% من القيمة السوقية للأسهم مباشرة إن عجز عن تفصيل الأصول…'
  WHERE id = '0389afb8-4a4a-4c45-ada5-b3cd47094ad1';
UPDATE sharia_rulings SET summary = 'استقبال القبلة شرط صحة الصلاة. والحِكم فيه: 1- توحيد المسلمين نحو جهة واحدة. 2- التذكير بإبراهيم الخليل وبيته العتيق. 3- رمز الوحدة الإسلامية. 4- التمييز بين صلاتنا وصلاة غيرنا…'
  WHERE id = '03a444a4-ac52-47e3-a94d-45f6b2c3601d';
UPDATE sharia_rulings SET summary = 'يُستحب عند سماع الأذان: (1) متابعة المؤذن بترديد ما يقوله كلمة بكلمة. (2) عند الحيعلتين يقول: «لا حول ولا قوة إلا بالله». (3) بعد الأذان يصلي على النبي ﷺ ثم يقول: «اللهم رب هذه الدعوة التامة والصلاة القائمة، آتِ محمداً الوسيلة والفضيلة وابعثه مقاماً محموداً الذي وعدته»…'
  WHERE id = '03b1ad16-3f56-415a-b57b-21661dd1ac1a';
UPDATE sharia_rulings SET summary = 'العمرة جائزة في أشهر الحج بل هي أفضل لأن النبي ﷺ اعتمر في ذي القعدة مرات. ومن كان بمكة يُحرم بالعمرة من أدنى الحل (التنعيم). وأفضل العمرة عمرة رمضان التي تعدل حجة.'
  WHERE id = '0498c08d-9fa2-4c6e-8cbf-8b62600dfc7a';
UPDATE sharia_rulings SET summary = 'الحديث الموضوع: ما اختُلق ونُسب كذباً للنبي ﷺ. وعلاماته: اعتراف الواضع بالوضع، أو أن في سنده كذاب معروف، أو ركاكة لفظه، أو مخالفته لصريح القرآن أو الحديث الصحيح أو الحقائق الثابتة…'
  WHERE id = '04b00a8b-974e-42b0-a135-8e1aad775729';
UPDATE sharia_rulings SET summary = 'مرّ النبي ﷺ قبل الوحي بثلاث مراحل تهيئة: (1) الرؤيا الصادقة — كانت تأتيه كفلق الصبح وتتحقق. (2) التعبّد والخلوة — كان يتحنث في غار حراء قبل البعثة بأشهر. (3) تحبيب الخلوة إليه — حبّب الله إليه العزلة والتأمل…'
  WHERE id = '04ed50a9-fe25-4380-a472-8eccae485269';
UPDATE sharia_rulings SET summary = 'الأصل في الذكر الإسرار إلا ما دل الدليل على استحباب الجهر به. فيستحب الجهر بالتهليل والتكبير في مواطن معينة كالعيدين والحج وأدبار الصلوات، ويستحب الإسرار في أذكار الصباح والمساء وذكر الله في أوقات الخلوة…'
  WHERE id = '05cf654d-69de-460a-b038-e4be565413ff';
UPDATE sharia_rulings SET summary = '(1) الإرسال: سقوط راوٍ من آخر السند دون تعمد الإيهام، كقول التابعي ''قال النبي ﷺ'' دون ذكر الصحابي. الحديث المرسل حجة عند مالك وأبي حنيفة، وضعيف عند الشافعي وأكثر المحدثين…'
  WHERE id = '065e72f3-cc5c-4849-9fb1-f4cf5f2b0f0f';
UPDATE sharia_rulings SET summary = 'أيام التشريق هي الحادي عشر والثاني عشر والثالث عشر من ذي الحجة. أعمالها: (1) رمي الجمرات الثلاث يومياً بعد الزوال (7 حصيات لكل جمرة). (2) المبيت بمنى ليالي أيام التشريق…'
  WHERE id = '07769ecb-07b9-45c0-b471-790fd1432ce2';
UPDATE sharia_rulings SET summary = 'من أذكار النوم المأثورة: (1) قراءة آية الكرسي —من قرأها لم يزل عليه من الله حافظ حتى يصبح—. (2) قراءة {قُلْ هُوَ اللَّهُ أَحَدٌ} والمعوذتين ثلاث مرات والنفث على الجسد…'
  WHERE id = '098dd211-2d3e-4056-a354-77f0b5945c58';
UPDATE sharia_rulings SET summary = 'التيمم بدل عن الوضوء والغسل عند: (1) عدم وجود الماء. (2) العجز عن استعماله لمرض يضره الماء. (3) الخشية من شدة البرد بلا وجود ما يُسخَّن به (عند بعضهم). وكيفيته: ضربة واحدة بيديه على التراب الطاهر، ثم يمسح وجهه بهما، ثم يمسح يديه إلى الرسغين…'
  WHERE id = '09984628-72df-45c1-8b90-e23bb2a0f9b9';
UPDATE sharia_rulings SET summary = 'أذكار الصباح سنة مؤكدة يبدأ وقتها من الفجر وينتهي بطلوع الشمس، ومنها: قراءة آية الكرسي مرة واحدة، وسورة الإخلاص والمعوذتين ثلاث مرات، وذكر «أصبحنا وأصبح الملك لله»، وذكر «اللهم بك أصبحنا وبك أمسينا»…'
  WHERE id = '0af44724-f9d1-476f-8b83-5e4f6e9b0704';
UPDATE sharia_rulings SET summary = 'الغيبة: ذكرك أخاك بما يكرهه وهو غائب. النبي ﷺ: ''أتدرون ما الغيبة؟ ذكرك أخاك بما يكره''. إن كان ما قيل صحيحاً فغيبة، وإن كان كذباً ففيه البهتان. النميمة: نقل الكلام بين الناس لإفساد العلاقات…'
  WHERE id = '0ea342b4-f131-43f0-be33-e09066afaf12';
UPDATE sharia_rulings SET summary = 'المجتهد: هو العالم المستوفي شروط الاجتهاد الذي يستنبط الأحكام من الأدلة التفصيلية. المقلِّد: هو من يأخذ بقول العالم دون معرفة دليله. المتّبع: هو من يأخذ بقول العالم مع معرفة دليله والاقتناع به — وهو أعلى درجة من المقلد…'
  WHERE id = '10d32cfd-bcc3-482d-ac11-e61ad9755aa0';
UPDATE sharia_rulings SET summary = 'تميّز النبي ﷺ بسمات قيادية وأخلاقية فريدة: (1) الرحمة والرفق — «ما بُعثتُ لعَّاناً، وإنما بُعثتُ رحمةً». (2) الشجاعة — كان أشجع الناس في المعارك ويثبت حين يفرّ غيره…'
  WHERE id = '1133f1cf-dbe3-4386-bb90-478fdf021695';
UPDATE sharia_rulings SET summary = 'الرسول: من أوحى الله إليه بشريعة جديدة وأُرسل إلى قوم يدعوهم إليها. النبي: من أوحى الله إليه ليُبلِّغ شريعة من سبقه دون شريعة جديدة. فكل رسول نبي وليس كل نبي رسولاً…'
  WHERE id = '14d9cd6d-21ee-41b6-be9f-03882af2e57c';
UPDATE sharia_rulings SET summary = 'كان النبي ﷺ نموذجاً للزوج والأب الكريم؛ قال ﷺ: «خيركم خيركم لأهله وأنا خيركم لأهلي». من مظاهر ذلك: (1) مساعدته أهله في أعمال البيت — كان يخصف نعله ويخيط ثوبه ويحلب شاته…'
  WHERE id = '15ccf8af-c6f7-4896-a955-e4f27a305d2e';
UPDATE sharia_rulings SET summary = '(1) الفرض عند الجمهور: ما ثبت بدليل قطعي كالصلوات الخمس والحج، تاركه آثم ومستحق للعقوبة. (2) الواجب عند الأحناف: ما ثبت بدليل ظني كالوتر، تاركه آثم لكن دون مستوى الفرض…'
  WHERE id = '16aeb388-7816-4194-922b-2d12b703ad0d';
UPDATE sharia_rulings SET summary = 'الكذب محرَّم شرعاً وهو من الكبائر المُهلِكة. قال النبي صلى الله عليه وسلم: (إياكم والكذب؛ فإن الكذب يهدي إلى الفجور، وإن الفجور يهدي إلى النار). رواه البخاري ومسلم…'
  WHERE id = '17dc802e-c363-481c-904d-a8b6782f9b16';
UPDATE sharia_rulings SET summary = 'عروض التجارة: كل ما يُعدّ للبيع من بضاعة وسلع. وتجب فيها الزكاة عند جمهور العلماء. وكيفية الحساب: يُقيَّم المالُ التجاري آخر كل حول بقيمته السوقية (يوم الإخراج)، ويُضاف إليه ما عنده من نقود وديون مرجوة، ويُخصم منه الديون الواجبة عليه…'
  WHERE id = '1a820c37-1522-4f30-a426-44737cef71bf';
UPDATE sharia_rulings SET summary = 'أركان عقد الزواج هي: (1) الإيجاب من ولي المرأة أو من ينوب عنه. (2) القبول من الزوج. وشروط صحته: (أ) الولي: لا نكاح إلا بولي عند جمهور العلماء لقوله ﷺ: ''لا نكاح إلا بولي''…'
  WHERE id = '1c16d394-6aa7-4318-8c07-612f61bca177';
UPDATE sharia_rulings SET summary = 'نبي الله داود عليه السلام، قال تعالى: (وَآتَيْنَا دَاوُودَ زَبُورًا) [النساء: 163]. والزبور كتاب الله المُنزَّل على داود، وكان داود أحسن الناس صوتاً، وكانت الجبال والطير تُسبّح معه.'
  WHERE id = '1ce2a4cc-2c96-489e-98cb-58527b78d020';
UPDATE sharia_rulings SET summary = 'أحكام الإرث مُفصَّلة في سورة النساء. الزوجة: ربع إن لم يكن للزوج ولد، ثمن إن كان له ولد. البنت: نصف إن كانت واحدة، ثلثان إن كانتا فأكثر، العصبة مع البنين (للذكر مثل حظ الأنثيين)…'
  WHERE id = '20520623-3403-4211-9b36-3387c0565aa3';
UPDATE sharia_rulings SET summary = 'تجارة الأسهم في البورصة مباحة بضوابط: (1) أن تكون شركة النشاط الرئيسي مباحاً. (2) أن تتضمن الصفقة تسليماً فعلياً لا مجرد مضاربة على السعر. (3) ألا تكون الشركة ذات نشاط محرَّم أصلاً (كالبنوك الربوية، والخمور، والسلاح المحرَّم)…'
  WHERE id = '22435765-e82e-4c4e-9f93-c9cb0d0a12df';
UPDATE sharia_rulings SET summary = 'اختلف العلماء: فذهب الشافعية والحنابلة إلى وجوبها على المأموم في السرية والجهرية. وذهب الحنفية إلى عدم وجوبها على المأموم اكتفاءً بقراءة الإمام. ومذهب المالكية التفريق بين السرية (تجب) والجهرية (لا تجب)…'
  WHERE id = '24bc296d-6bca-4643-bf3f-e6063c1cf544';
UPDATE sharia_rulings SET summary = 'أفضل صلاة النافلة قيام الليل (التهجد). قال النبي ﷺ: ''أفضل الصلاة بعد الفريضة صلاة الليل'' (رواه مسلم). هيئة صلاة النبي ﷺ في الليل: (1) كان يقوم حتى تتورم قدماه فيقال له فتقول عائشة ''أفلا أكون عبداً شكوراً''…'
  WHERE id = '25bd9c52-75f6-4ae5-9aa2-10f9fdcbb4db';
UPDATE sharia_rulings SET summary = 'يوسف بن يعقوب بن إسحاق بن إبراهيم عليهم السلام. قصته ملخصة: حسده إخوته وألقوه في الجب وباعوه لقافلة. اشتراه عزيز مصر. راودته امرأة العزيز عن نفسه فاستعصم واستجار بالله…'
  WHERE id = '25c3ba27-e60b-4952-9920-8e81a365ff98';
UPDATE sharia_rulings SET summary = 'سليمان بن داود عليهما السلام أُوتي ملكاً عظيماً لم يُؤتَه أحد بعده. معجزاته: (1) تسخير الريح تجري بأمره. (2) تسخير الجن بناءً ومعادن. (3) تعليم منطق الطير. (4) جُنده من الجن والإنس والطير…'
  WHERE id = '286923b6-7c7a-4d3c-9ea1-4d65cb662b4a';
COMMIT;
